const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon([
    [
      [-90.9, 29.07],
      [-90.65, 29.07],
      [-90.65, 29.17],
      [-90.9, 29.17],
      [-90.9, 29.07]
    ]
  ]); // Approximate Isles Dernières Barrier Islands

  // 2. Data Acquisition - Landsat for land/water classification
  const getLandMask = (startDate, endDate) => {
    // Use Landsat 7 for 2000 and Landsat 8/9 for 2024
    let collection;
    if (startDate.getFullYear() < 2003) {
      collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(geometry);
    } else {
      collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
        .filterDate(startDate, endDate)
        .filterBounds(geometry);
    }

    if (collection.size().getInfo() === 0) return null;

    // Create cloud-free composite
    const composite = collection
      .map(img => {
        // Cloud mask using QA band
        const qa = img.select('QA_PIXEL');
        const cloudMask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
          .and(qa.bitwiseAnd(1 << 5).eq(0)); // Cloud shadow
        return img.updateMask(cloudMask);
      })
      .median()
      .clip(geometry);

    // Calculate MNDWI for water detection
    // Landsat 7: Green = B2, SWIR1 = B5
    // Landsat 8/9: Green = B3, SWIR1 = B6
    let green, swir;
    if (startDate.getFullYear() < 2003) {
      green = composite.select('SR_B2');
      swir = composite.select('SR_B5');
    } else {
      green = composite.select('SR_B3');
      swir = composite.select('SR_B6');
    }

    const mndwi = green.subtract(swir).divide(green.add(swir));
    // Land mask = pixels with MNDWI < 0 (water < 0, land >= 0)
    const landMask = mndwi.gte(0);

    return landMask;
  };

  // Analyze 2000 and 2024 periods
  const masks2000 = getLandMask(new Date('2000-01-01'), new Date('2000-12-31'));
  const masks2024 = getLandMask(new Date('2024-01-01'), new Date('2024-12-31'));

  // 3. Check for empty collections
  if (!masks2000 || !masks2024) {
    console.log("2000 Images: 0");
    console.log("2024 Images: 0");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Calculate land area in square meters
  const calculateLandArea = (landMask) => {
    const pixelArea = landMask.multiply(ee.Image.pixelArea()); // Area in m² for land pixels
    const stats = pixelArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 30,
      maxPixels: 1e9
    });
    return stats.getNumber('constant').getInfo();
  };

  const area2000 = calculateLandArea(masks2000);
  const area2024 = calculateLandArea(masks2024);

  // 5. Validation
  console.log(`2000 Land Area: ${area2000.toFixed(0)} m²`);
  console.log(`2024 Land Area: ${area2024.toFixed(0)} m²`);
  console.log(`Area Ratio: ${(area2024/area2000).toFixed(3)}`);

  if (area2000 === 0 || area2024 === 0) {
    console.log("<answer>C2</answer>");
  } else if (area2000 === null || area2024 === null || 
             isNaN(area2000) || isNaN(area2024) ||
             area2000 < 0 || area2024 < 0) {
    console.log("<answer>C3</answer>");
  } else if (area2024 < area2000 * 0.5) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
